209	        }
210	
211	        memmove(dst, src, (size_t)chunk_sz);
212	        dst += chunk_sz;
213	        src += chunk_sz;
214	
215	        if (src + 2 <= end && src[0] == '\r' && src[1] == '\n') {
216	            src += 2;
217	        }
218	    }
219	
220	    return (size_t)(dst - buf);
221	}
