224	/* ov_tls_ctx_t 不透明句柄声明在 runtime_openvela.h；完整定义在此。
225	 * ov_tls_connect / ov_tls_read / ov_tls_write / ov_tls_ctx_free
226	 * 供同固件应用层复用 TLS 连接。 */
227	
228	struct ov_tls_ctx {
229	    mbedtls_ssl_context ssl;
230	    mbedtls_ssl_config cfg;
231	    mbedtls_net_context net;
232	    mbedtls_ctr_drbg_context ctr_drbg;
