236	/* 等待 TLS 底层 fd 可读/可写（poll，带超时）。返回 0 就绪，-1 超时/错误。 */
237	static int ov_tls_wait_fd(const ov_tls_ctx_t *ctx, short events,
238	                          uint32_t timeout_ms, const char *phase)
239	{
240	    struct pollfd descriptor;
241	    int result;
242	
243	    if (!ctx || ctx->net.fd < 0) {
244	        ov_tls_diag("phase=%s wait invalid fd=%d events=0x%x",
245	                    phase ? phase : "tls", ctx ? ctx->net.fd : -1,
246	                    (unsigned int)events);
247	        return -1;
248	    }
249	    descriptor.fd = ctx->net.fd;
250	    descriptor.events = events;
251	    descriptor.revents = 0;
252	    result = poll(&descriptor, 1, (int)timeout_ms);
253	    if (result == 0) {
254	        ov_tls_diag("phase=%s wait timeout fd=%d events=0x%x timeout_ms=%u",
255	                    phase ? phase : "tls", descriptor.fd,
256	                    (unsigned int)events, timeout_ms);
257	        return -1;
258	    }
259	    if (result < 0) {
260	        ov_tls_diag("phase=%s wait poll_failed fd=%d events=0x%x errno=%d",
261	                    phase ? phase : "tls", descriptor.fd,
262	                    (unsigned int)events, errno);
263	        return -1;
264	    }
265	    ov_tls_diag("phase=%s wait ready fd=%d events=0x%x revents=0x%x",
266	                phase ? phase : "tls", descriptor.fd,
267	                (unsigned int)events, (unsigned int)descriptor.revents);
268	    if (descriptor.revents & (POLLERR | POLLHUP | POLLNVAL)) {
269	        ov_tls_diag("phase=%s wait socket_error fd=%d revents=0x%x",
270	                    phase ? phase : "tls", descriptor.fd,
271	                    (unsigned int)descriptor.revents);
272	        return -1;
273	    }
274	    return 0;
275	}
276	
277	static uint64_t ov_tls_monotonic_ms(void)
278	{
279	    struct timespec value;
280	
281	    if (clock_gettime(CLOCK_MONOTONIC, &value) != 0) {
282	        return 0;
283	    }
284	    return (uint64_t)value.tv_sec * 1000u + (uint64_t)value.tv_nsec / 1000000u;
285	}
286	
287	static uint32_t ov_tls_remaining_ms(uint64_t deadline_ms)
288	{
289	    uint64_t now = ov_tls_monotonic_ms();
290	    uint64_t remaining;
291	
292	    if (!now || !deadline_ms) {
293	        return 0u;
294	    }
295	    if (now >= deadline_ms) {
296	        return 0u;
297	    }
298	    remaining = deadline_ms - now;
299	    return remaining > UINT32_MAX ? UINT32_MAX : (uint32_t)remaining;
300	}
301	
302	static int ov_tls_wait_io(ov_tls_ctx_t *ctx, int tls_ret,
303	                          uint64_t deadline_ms,
304	                          uint32_t fallback_timeout_ms,
305	                          const char *phase)
306	{
307	    short events;
308	    uint32_t remaining_ms;
309	
310	    if (tls_ret == MBEDTLS_ERR_SSL_WANT_READ) {
311	        events = POLLIN;
312	    } else if (tls_ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
313	        events = POLLOUT;
314	    } else {
315	        return AGENT_ERROR_NETWORK;
316	    }
317	
318	    remaining_ms = deadline_ms ? ov_tls_remaining_ms(deadline_ms) :
319	                   fallback_timeout_ms;
320	    if (remaining_ms == 0u ||
321	        ov_tls_wait_fd(ctx, events, remaining_ms, phase) != 0) {
322	        return AGENT_ERROR_TIMEOUT;
323	    }
324	
325	    return AGENT_OK;
326	}
