341	ssize_t ov_tls_read(ov_tls_ctx_t *ctx, void *buffer, size_t length,
342	                    uint32_t timeout_ms)
343	{
344	    if (!ctx || !buffer) {
345	        errno = EINVAL;

344	    if (!ctx || !buffer) {
345	        errno = EINVAL;
346	        return -1;
347	    }
348	    for (;;) {
349	        int count = mbedtls_ssl_read(&ctx->ssl, buffer, length);
350	
351	        if (count == MBEDTLS_ERR_SSL_WANT_READ) {
352	            if (timeout_ms == 0u) {
353	                continue;
354	            }
355	            if (ov_tls_wait_fd(ctx, POLLIN, timeout_ms, "tls_read") != 0) {
356	                errno = ETIMEDOUT;
357	                return -1;
358	            }
359	            continue;
360	        }
361	        if (count == MBEDTLS_ERR_SSL_WANT_WRITE) {
362	            if (ov_tls_wait_fd(ctx, POLLOUT, timeout_ms, "tls_read") != 0) {
363	                errno = ETIMEDOUT;
364	                return -1;
365	            }
366	            continue;
367	        }
368	        if (count < 0) {
369	            errno = EIO;
370	            return -1;
371	        }
372	        return (ssize_t)count;
373	    }
374	}
