376	ssize_t ov_tls_write(ov_tls_ctx_t *ctx, const void *buffer, size_t length,
377	                     uint32_t timeout_ms)
378	{
379	    if (!ctx || !buffer) {
380	        errno = EINVAL;
381	        return -1;
382	    }
383	    for (;;) {
384	        int count = mbedtls_ssl_write(&ctx->ssl, buffer, length);
385	
386	        if (count == MBEDTLS_ERR_SSL_WANT_WRITE) {
387	            if (timeout_ms == 0u) {
388	                continue;
389	            }
390	            if (ov_tls_wait_fd(ctx, POLLOUT, timeout_ms, "tls_write") != 0) {
391	                errno = ETIMEDOUT;
392	                return -1;
393	            }
394	            continue;
395	        }
396	        if (count == MBEDTLS_ERR_SSL_WANT_READ) {
397	            if (ov_tls_wait_fd(ctx, POLLIN, timeout_ms, "tls_write") != 0) {
398	                errno = ETIMEDOUT;
399	                return -1;
400	            }
401	            continue;
402	        }
403	        if (count < 0) {
404	            errno = EIO;
405	            return -1;
406	        }
407	        return (ssize_t)count;
408	    }
409	}
