442	int ov_tls_connect(ov_tls_ctx_t *ctx,
443	                   const char *host,
444	                   const char *port,
445	                   uint32_t timeout_ms)
446	{
447	    int ret;
448	    const char *pers = "cagent_ov";
449	    uint32_t effective_timeout_ms;
450	    uint64_t deadline_ms;
451	
452	    ov_mem_region_log("tls-context", ctx);
453	    ov_mem_diag("tls-connect-before");
454	    mbedtls_ssl_init(&ctx->ssl);
455	    mbedtls_ssl_config_init(&ctx->cfg);
456	    mbedtls_net_init(&ctx->net);
457	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
458	    mbedtls_entropy_init(&ctx->entropy);
459	
460	    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, mbedtls_entropy_func,
461	                                 &ctx->entropy,
462	                                 (const unsigned char *)pers, strlen(pers));
463	    if (ret != 0) {
464	        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=-0x%04x\n", OV_TAG, -ret);
465	        ov_tls_diag_mbed("ctr_drbg_seed", ret);
466	        return AGENT_ERROR_NETWORK;
467	    }
468	
469	    effective_timeout_ms = timeout_ms ? timeout_ms :
470	                           CAGENT_OV_SOCKET_TIMEOUT_SEC * 1000u;
471	    deadline_ms = ov_tls_monotonic_ms();
472	    if (deadline_ms) {
473	        deadline_ms += effective_timeout_ms;
474	    }
475	
476	    ov_tls_diag("connecting %s:%s (timeout %u ms)",
477	                host, port, effective_timeout_ms);
478	    fflush(stdout);
479	
480	    /* Use non-blocking connect with select() to enforce a timeout.
481	     * mbedtls_net_connect() blocks indefinitely on NuttX when the
482	     * remote port is filtered (no SYN-ACK, no RST).
483	     */
484	
485	    {
486	        struct timeval tv_conn = {
487	            .tv_sec = (time_t)(effective_timeout_ms / 1000u),
488	            .tv_usec = (suseconds_t)(effective_timeout_ms % 1000u) * 1000,
489	        };
490	        struct addrinfo hints = { .ai_family = AF_INET,
491	                                  .ai_socktype = SOCK_STREAM };
492	        struct addrinfo *res = NULL;
493	        int fd;
494	
495	        ov_tls_diag("phase=dns resolving host=%s port=%s", host, port);
496	        fflush(stdout);
497	
498	        {
499	            int dns_rc = getaddrinfo(host, port, &hints, &res);
500	
501	            if (dns_rc != 0 || !res) {
502	                ov_tls_diag("phase=dns failed host=%s port=%s rc=%d errno=%d",
503	                            host, port, dns_rc, errno);
504	                return AGENT_ERROR_NETWORK;
505	            }
506	            ov_tls_diag("phase=dns resolved host=%s family=%d socktype=%d",
507	                        host, res->ai_family, res->ai_socktype);
508	        }
509	
510	        if (res->ai_family != AF_INET || !res->ai_addr) {
511	            ov_tls_diag("phase=dns unsupported result host=%s family=%d",
512	                        host, res->ai_family);
513	            freeaddrinfo(res);
514	            return AGENT_ERROR_NETWORK;
515	        }
516	
517	        {
518	            char peer_text[INET_ADDRSTRLEN];
519	            const struct sockaddr_in *peer =
520	                (const struct sockaddr_in *)res->ai_addr;
521	
522	            if (inet_ntop(AF_INET, &peer->sin_addr, peer_text,
523	                          sizeof(peer_text))) {
524	                ov_tls_diag("phase=tcp peer=%s port=%s", peer_text, port);
525	            }
526	        }
527	
528	        ov_tls_diag("phase=tcp creating socket ...");
529	        fflush(stdout);
530	
531	        fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
532	        if (fd < 0) {
533	            freeaddrinfo(res);
534	            ov_tls_diag("socket() failed errno=%d", errno);
535	            return AGENT_ERROR_NETWORK;
536	        }
537	
538	        ov_tls_diag("phase=tcp connect_start fd=%d nonblocking=1", fd);
539	        fflush(stdout);
540	
541	        /* Non-blocking connect */
542	
543	        int flags = fcntl(fd, F_GETFL, 0);
544	        fcntl(fd, F_SETFL, flags | O_NONBLOCK);
545	
546	        ret = connect(fd, res->ai_addr, res->ai_addrlen);
547	        if (ret < 0 && errno == EINPROGRESS) {
548	            fd_set wfds;
549	            FD_ZERO(&wfds);
550	            FD_SET(fd, &wfds);
551	
552	            ret = select(fd + 1, NULL, &wfds, NULL, &tv_conn);
553	            if (ret == 0) {
554	                ov_tls_diag("phase=tcp connect_timeout fd=%d timeout_ms=%u",
555	                            fd, effective_timeout_ms);
556	                close(fd);
557	                freeaddrinfo(res);
558	                return AGENT_ERROR_NETWORK;
559	            }
560	            if (ret < 0) {
561	                ov_tls_diag("phase=tcp select_failed fd=%d errno=%d",
562	                            fd, errno);
563	                close(fd);
564	                freeaddrinfo(res);
565	                return AGENT_ERROR_NETWORK;
566	            }
567	
568	            /* Check if connect succeeded */
569	
570	            int err = 0;
571	            socklen_t elen = sizeof(err);
572	            ret = getsockopt(fd, SOL_SOCKET, SO_ERROR, &err, &elen);
573	            if (ret < 0) {
574	                ov_tls_diag("phase=tcp getsockopt_failed fd=%d errno=%d",
575	                            fd, errno);
576	                close(fd);
577	                freeaddrinfo(res);
578	                return AGENT_ERROR_NETWORK;
579	            }
580	            if (err != 0) {
581	                ov_tls_diag("phase=tcp connect_failed fd=%d so_error=%d",
582	                            fd, err);
583	                close(fd);

584	                freeaddrinfo(res);
585	                return AGENT_ERROR_NETWORK;
586	            }
587	        } else if (ret < 0) {
588	            ov_tls_diag("phase=tcp connect_failed_immediate fd=%d errno=%d",
589	                        fd, errno);
590	            close(fd);
591	            freeaddrinfo(res);
592	            return AGENT_ERROR_NETWORK;
593	        }
594	
595	        freeaddrinfo(res);
596	
597	        /* 保持非阻塞模式：mbedTLS 返回 WANT_READ/WANT_WRITE，
598	         * 由 ov_tls_read/ov_tls_write 的 poll 循环控制超时。
599	         * 不要恢复阻塞，否则阻塞读无法超时。 */
600	
601	        ctx->net.fd = fd;
602	    }
603	
604	    ov_tls_diag("phase=tcp connected host=%s port=%s fd=%d",
605	                host, port, ctx->net.fd);
606	
607	    if ((ret = mbedtls_ssl_config_defaults(&ctx->cfg,
608	                                            MBEDTLS_SSL_IS_CLIENT,
609	                                            MBEDTLS_SSL_TRANSPORT_STREAM,
610	                                            MBEDTLS_SSL_PRESET_DEFAULT)) != 0) {
611	        syslog(LOG_ERR, "[%s] ssl_config_defaults ret=-0x%04x\n", OV_TAG, -ret);
612	        ov_tls_diag_mbed("ssl_config_defaults", ret);
613	        return AGENT_ERROR_NETWORK;
614	    }
615	
616	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
617	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
618	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
619	#else
620	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
621	#endif
622	
623	#if 0 /* Disabled: some servers reject the connection when ALPN is present */
624	#if defined(MBEDTLS_SSL_ALPN)
625	    {
626	        static const char *alpn_protos[] = { "http/1.1", NULL };
627	        mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn_protos);
628	    }
629	#endif
630	#endif
631	
632	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
633	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);
634	
635	    if ((ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg)) != 0) {
636	        syslog(LOG_ERR, "[%s] ssl_setup ret=-0x%04x\n", OV_TAG, -ret);
637	        ov_tls_diag_mbed("ssl_setup", ret);
638	        return AGENT_ERROR_NETWORK;
639	    }
640	    ov_mem_diag("tls-setup-after");
641	
642	    if ((ret = mbedtls_ssl_set_hostname(&ctx->ssl, host)) != 0) {
643	        syslog(LOG_ERR, "[%s] ssl_set_hostname ret=-0x%04x\n", OV_TAG, -ret);
644	        ov_tls_diag_mbed("ssl_set_hostname", ret);
645	        return AGENT_ERROR_NETWORK;
646	    }
647	
648	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
649	                        mbedtls_net_send, mbedtls_net_recv, NULL);
650	
651	    ov_mem_diag("tls-handshake-before");
652	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
653	        uint32_t remaining_ms;
654	
655	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
656	#if defined(MBEDTLS_ERROR_C)
657	            char err_buf[128];
658	            mbedtls_strerror(ret, err_buf, sizeof(err_buf));
659	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x: %s\n",
660	                   OV_TAG, -ret, err_buf);
661	#else
662	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x\n", OV_TAG, -ret);
663	#endif
664	            ov_tls_diag_mbed("ssl_handshake", ret);
665	            return AGENT_ERROR_NETWORK;
666	        }
667	        ov_tls_diag("phase=tls handshake_wait fd=%d want=%s",
668	                    ctx->net.fd,
669	                    ret == MBEDTLS_ERR_SSL_WANT_READ ? "read" : "write");
670	        remaining_ms = deadline_ms ? ov_tls_remaining_ms(deadline_ms) :
671	                       effective_timeout_ms;
672	        if (remaining_ms == 0u
673	            || ov_tls_wait_fd(ctx,
674	                              ret == MBEDTLS_ERR_SSL_WANT_READ ? POLLIN : POLLOUT,
675	                              remaining_ms, "tls_handshake") != 0) {
676	            ov_tls_diag("phase=tls handshake_wait_failed fd=%d remaining_ms=%u",
677	                        ctx->net.fd, remaining_ms);
678	            return AGENT_ERROR_TIMEOUT;
679	        }
680	    }
681	
682	    syslog(LOG_INFO, "[%s] TLS handshake OK: %s / %s\n",
683	           OV_TAG, mbedtls_ssl_get_version(&ctx->ssl),
684	           mbedtls_ssl_get_ciphersuite(&ctx->ssl));
685	    ov_tls_diag("phase=tls handshake_ok version=%s cipher=%s fd=%d",
686	                mbedtls_ssl_get_version(&ctx->ssl),
687	                mbedtls_ssl_get_ciphersuite(&ctx->ssl), ctx->net.fd);
688	    ov_mem_diag("tls-handshake-after");
689	
690	    return AGENT_OK;
691	}
692	
693	/* ── HTTP/1.1 request write ─────────────────────────────────── */
694	
695	static int ov_tls_write_request(ov_tls_ctx_t *ctx,
696	                                 const char *method,
697	                                 const char *host,
698	                                 const char *path,
699	                                 const char *headers_str,
700	                                 const char *body,
701	                                 size_t body_len)
702	{
703	    char *hdr = malloc(CAGENT_OV_TLS_HDR_BUF_SIZE);
704	    if (!hdr) {
705	        return AGENT_ERROR_NOMEM;
706	    }
707	    ov_mem_region_log("tls-header-buffer", hdr);
708	
709	    int pos = 0;
710	    int n;
711	    int ret;
712	
713	#define HDR_APPEND(fmt, ...)                                            \
714	    n = snprintf(hdr + pos, CAGENT_OV_TLS_HDR_BUF_SIZE - pos,          \
715	                 fmt, ##__VA_ARGS__);                                   \
716	    if (n < 0 || pos + n >= (int)CAGENT_OV_TLS_HDR_BUF_SIZE) {        \
717	        free(hdr);                                                      \
718	        return AGENT_ERROR_LIMIT;                                       \
719	    }                                                                   \
720	    pos += n;
721	
722	    HDR_APPEND("%s %s HTTP/1.1\r\n", method, path);
723	    HDR_APPEND("Host: %s\r\n", host);
724	    HDR_APPEND("Connection: close\r\n");
725	    HDR_APPEND("User-Agent: cagent-openvela/1.0\r\n");
726	
727	    if (body && body_len > 0) {
728	        HDR_APPEND("Content-Length: %zu\r\n", body_len);
729	    }
730	
731	    if (headers_str && headers_str[0] != '\0') {
732	        HDR_APPEND("%s", headers_str);
733	    }
734	
735	    HDR_APPEND("\r\n");
736	#undef HDR_APPEND
737	
738	    int written = 0;
739	    while (written < pos) {
740	        ret = mbedtls_ssl_write(&ctx->ssl,
741	                                (const unsigned char *)(hdr + written),
742	                                (size_t)(pos - written));
743	        if (ret > 0) {
744	            written += ret;
745	        } else if (ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
746	            continue;
747	        } else {
748	            ov_tls_diag_mbed("ssl_write header", ret);
749	            free(hdr);
750	            return AGENT_ERROR_NETWORK;
751	        }
752	    }
753	
754	    free(hdr);
755	
756	    if (body && body_len > 0) {
757	        size_t bw = 0;
758	        while (bw < body_len) {
759	            ret = mbedtls_ssl_write(&ctx->ssl,
760	                                    (const unsigned char *)(body + bw),
761	                                    body_len - bw);
762	            if (ret > 0) {
763	                bw += (size_t)ret;
764	            } else if (ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
765	                continue;
766	            } else {
767	                ov_tls_diag_mbed("ssl_write body", ret);
768	                return AGENT_ERROR_NETWORK;
769	            }
770	        }
771	    }
772	
773	    return AGENT_OK;
774	}
775	
776	/* ── HTTP/1.1 response read ─────────────────────────────────── */
777	
778	static int ov_tls_read_response(ov_tls_ctx_t *ctx,
779	                                 char *resp_buf,
780	                                 size_t resp_cap,
781	                                 size_t *out_body_len,
782	                                 uint32_t timeout_ms)
783	{
784	    char *raw = malloc(CAGENT_OV_TLS_READ_BUF_SIZE);
785	    uint32_t effective_timeout_ms;
786	    uint64_t deadline_ms;
787	    if (!raw) {
788	        return AGENT_ERROR_NOMEM;
789	    }
790	    ov_mem_region_log("tls-read-buffer", raw);
