def apply_cmake_patch(dest: Path) -> None:
    cmake = dest / "CMakeLists.txt"
    text = cmake.read_text(encoding="utf-8")
    for in_tree, standalone in CMAKE_PATCH:
        if in_tree in text:
            text = text.replace(in_tree, standalone)
        elif standalone not in text:
            print(f"WARNING: CMake patch anchor not found for {in_tree[:40]}...",
                  file=sys.stderr)
    cmake.write_text(text, encoding="utf-8")


